"use client"

import { useEffect, useState } from "react"
import { PortalShell, StateMessage } from "../../components/PortalShell"
import { api } from "../../lib/api"

type Product = { id: string; name: string; sku: string; status: string; imageUrl?: string | null; category: { name: string }; unit: { code: string }; prices?: { price: string | number }[] }
type Identity = { vendor: { id: string } | null }

export default function VendorProducts() {
  const [vendorId, setVendorId] = useState(""); const [products, setProducts] = useState<Product[]>([]); const [editingId, setEditingId] = useState(""); const [imageDraft, setImageDraft] = useState(""); const [message, setMessage] = useState(""); const [error, setError] = useState("")
  async function load() { try { const identity = await api<Identity>("/api/v1/marketplace/me"); if (!identity.vendor) throw new Error("Vendor access is not configured"); setVendorId(identity.vendor.id); setProducts(await api<Product[]>(`/api/v1/marketplace/vendors/${identity.vendor.id}/products`)) } catch (e) { setError(e instanceof Error ? e.message : "Unable to load products") } }
  useEffect(() => { load() }, [])
  async function toggle(product: Product) { try { await api(`/api/v1/marketplace/vendors/${vendorId}/products/${product.id}`, { method: "PATCH", body: JSON.stringify({ status: product.status === "ACTIVE" ? "INACTIVE" : "ACTIVE" }) }); setMessage("Product status updated"); load() } catch (e) { setError(e instanceof Error ? e.message : "Unable to update product") } }
  async function saveImage(product: Product) { try { await api(`/api/v1/marketplace/vendors/${vendorId}/products/${product.id}`, { method: "PATCH", body: JSON.stringify({ imageUrl: imageDraft.trim() || null }) }); setEditingId(""); setMessage("Product image URL saved"); load() } catch (e) { setError(e instanceof Error ? e.message : "Unable to update product image") } }
  return <PortalShell title="Vendor products" subtitle="Manage catalogue availability and product image URLs." links={[{ label: "Dashboard", href: "/vendor/dashboard" }, { label: "Products", href: "/vendor/products" }, { label: "Orders", href: "/vendor/orders" }, { label: "Delivery partners", href: "/vendor/delivery-partners" }, { label: "Payments", href: "/vendor/payments" }]}>{message && <StateMessage>{message}</StateMessage>}{error && <StateMessage error>{error}</StateMessage>}<section className="portal-panel">{products.length === 0 ? <div className="portal-empty">No products belong to this vendor.</div> : <table className="portal-table"><thead><tr><th>Product</th><th>Category</th><th>Unit</th><th>Price</th><th>Status</th><th>Image URL</th><th></th></tr></thead><tbody>{products.map((product) => <tr key={product.id}><td><strong>{product.name}</strong><small>{product.sku}</small></td><td>{product.category.name}</td><td>{product.unit.code}</td><td>₹{Number(product.prices?.[0]?.price || 0).toLocaleString("en-IN")}</td><td><span className={`status-badge ${product.status !== "ACTIVE" ? "warn" : ""}`}>{product.status}</span></td><td>{editingId === product.id ? <input value={imageDraft} onChange={(event) => setImageDraft(event.target.value)} placeholder="https://..." aria-label={`Image URL for ${product.name}`} /> : product.imageUrl ? <a href={product.imageUrl} target="_blank" rel="noreferrer">View image</a> : "Not set"}</td><td>{editingId === product.id ? <><button onClick={() => saveImage(product)}>Save image</button><button className="secondary" onClick={() => setEditingId("")}>Cancel</button></> : <><button onClick={() => { setEditingId(product.id); setImageDraft(product.imageUrl || "") }}>Edit image</button><button onClick={() => toggle(product)}>{product.status === "ACTIVE" ? "Disable" : "Activate"}</button></>}</td></tr>)}</tbody></table>}</section></PortalShell>
}
